const I18N_SKIP='.mp15,.tat,.verse,.qv,.aqt,.mkct,.aodt,.rcw,.tatf p,.mbasm,.aptx,#tfs,#ghr,.msura,.mkls,.mkl,.tav,textarea,.noi18n,script,style';
const I18N_Q=/[\u0670\u0671\u06D6-\u06ED]/;
const I18N_AR=/[؀-ۿ]/;
const i18nLat=s=>s.replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/٬/g,',').replace(/٫/g,'.');
let I18N_SRE=null, I18N_NAMES=null;
const I18N_C=new Map();
function i18nFill(t,nums,sur){ let i=0,j=0; return t.replace(/[#§]/g,c=>c==='#'?(nums[i++]??''):(sur[j]!=null?EN_NAMES[I18N_NAMES.indexOf(sur[j++])]||sur[j-1]:'')); }
const I18N_PAT=[
  [/^✨ تحديث جديد لخطة «(.+)»$/, m=>`✨ New update for "${m[1]}"`],
  [/^(حفظ جديد|مراجعة قريبة|مراجعة بعيدة|مراجعة|تلاوة): (.+)$/, m=>`${tr(m[1])}: ${tr(m[2])}`],
  [/^تختم المرحلة (.+)$/, m=>`Stage done by ${m[1]}`],
  [/^تختم خطتك (.+)$/, m=>`Plan done by ${m[1]}`],
  [/^ما لقينا آية فيها «(.+)»\./, m=>`No ayah found with "${m[1]}". Try the word without "ال" or with fewer letters.`],
  [/^أهلاً (.*?)(، حياك الله)?$/, m=>`Welcome ${m[1]}`.trim()],
  [/^انضممت لـ«(.+)»، بالتوفيق$/, m=>`You joined "${m[1]}", good luck`],
  [/^أنشئ خطتك، وتنضم مباشرة لـ«(.+)»$/, m=>`Create your plan, and you'll join "${m[1]}" right away`],
  [/^بدأت نفس خطة (.+)، بالتوفيق$/, m=>`You started the same plan as ${tr(m[1])}, good luck`],
  [/^ما شاء الله، أنجزت (.+) وانحسبت لك (.+)$/, m=>`Ma sha Allah, you completed ${tr(m[1])}: ${tr(m[2])} counted`],
  [/^حُمّلت سورة (.+?)، تسمعها بدون نت 🎧$/, m=>`Surah ${tr(m[1])} downloaded, listen offline 🎧`],
  [/^حُمّلت (.+?)، تسمعها بدون نت 🎧$/, m=>`${tr(m[1])} downloaded, listen offline 🎧`],
  [/^(.+) أوسمة جديدة، آخرها: (.+) 🎉$/, m=>`${m[1]} new badges, latest: ${tr(m[2])} 🎉`],
  [/^وسام جديد: (.+) 🎉$/, m=>`New badge: ${tr(m[1])} 🎉`],
  [/^(.+) أنهى ورده اليوم$/, m=>`${m[1]} finished today`],
  [/^\(وتنشال من (.+)\)$/, m=>`(removed from ${tr(m[1])})`],
  [/^نزّل (.+)$/, m=>`Shift ${tr(m[1])}`],
  [/^⬇ تحميل (.+)$/, m=>`⬇ Download ${tr(m[1])}`],
  [/^(.+) في (.+?)$/, m=>{ const a=tr(m[1]), b=tr(m[2]); return a!==m[1]&&b!==m[2]?`${a} in ${b}`:null; }],
];
function trRaw(t){
  if(t in EN) return EN[t];
  const nums=[]; const k=t.replace(/[0-9٠-٩]+(?:[٬,][0-9٠-٩]{3})*/g,m=>{ nums.push(i18nLat(m)); return '#'; });
  if(k in EN) return i18nFill(EN[k],nums,[]);
  if(!I18N_SRE){ I18N_NAMES=NAMES.slice(); I18N_SRE=new RegExp('(?<![\\u0600-\\u06FF])('+I18N_NAMES.slice().sort((a,b)=>b.length-a.length).map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\u0600-\\u06FF])','g'); }
  const sur=[]; const k2=k.replace(I18N_SRE,m=>{ sur.push(m); return '§'; });
  if(k2 in EN) return i18nFill(EN[k2],nums,sur);
  for(const [re,fn] of I18N_PAT){ const m=t.match(re); if(m){ const r=fn(m); if(r!=null) return r; } }
  for(const sep of [' · ','، ',' – ',' … ']) if(t.includes(sep)){ const ps=t.split(sep), out=ps.map(p=>tr(p)); if(out.some((x,i)=>x!==ps[i])) return out.join(sep==='، '?', ':sep); }
  return null;
}
const verTxt=()=>LANG==='en'?APP_VER:APP_VER.replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]).replace(/\./g,'٫');
function tr(s){
  if(LANG!=='en'||s==null) return s;
  s=String(s); const t=s.trim(); if(!t||!I18N_AR.test(t)||I18N_Q.test(t)) return s;
  let r=I18N_C.get(t);
  if(r===undefined){ r=trRaw(t); I18N_C.set(t,r); }
  if(r==null) return s;
  const lead=s.match(/^\s*/)[0], tail=s.match(/\s*$/)[0];
  return lead+r+tail;
}
const I18N_ATTR=['placeholder','title','aria-label'];
function i18nNode(root){
  if(LANG!=='en'||!root) return;
  if(root.nodeType===3){ const p=root.parentElement; if(p&&!p.closest(I18N_SKIP)){ const v=tr(root.data); if(v!==root.data) root.data=v; } return; }
  if(root.nodeType!==1) return;
  if(root.closest(I18N_SKIP)){ for(const e of [root,...root.querySelectorAll('[placeholder],[title],[aria-label]')]) for(const a of I18N_ATTR){ const v=e.getAttribute(a); if(v&&I18N_AR.test(v)){ const x=tr(v); if(x!==v) e.setAttribute(a,x); } } return; }
  const w=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT,{acceptNode:n=>n.nodeType===1&&n.matches(I18N_SKIP)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  let n;
  while((n=w.nextNode())){ if(n.nodeType===3&&I18N_AR.test(n.data)){ const v=tr(n.data); if(v!==n.data) n.data=v; } }
  for(const e of [root,...root.querySelectorAll('[placeholder],[title],[aria-label]')]) for(const a of I18N_ATTR){ const v=e.getAttribute&&e.getAttribute(a); if(v&&I18N_AR.test(v)){ const x=tr(v); if(x!==v) e.setAttribute(a,x); } }
}
function i18nStart(){
  if(LANG!=='en') return;
  document.documentElement.lang='en'; document.documentElement.dir='ltr'; document.documentElement.classList.add('en');
  document.querySelectorAll('[dir="rtl"]:not(textarea)').forEach(e=>{ if(e.matches('.wrap,.nav,body')) e.setAttribute('dir','ltr'); });
  document.title="Rabi' Al-Quran";
  i18nNode(document.body);
  new MutationObserver(ms=>{ for(const m of ms){
    if(m.type==='childList') m.addedNodes.forEach(i18nNode);
    else if(m.type==='characterData') i18nNode(m.target);
    else if(m.type==='attributes'){ const v=m.target.getAttribute(m.attributeName); if(v&&I18N_AR.test(v)){ const x=tr(v); if(x!==v) m.target.setAttribute(m.attributeName,x); } }
  } }).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:I18N_ATTR});
}
